```yaml
name: Remove SLO Label

on:
  workflow_run:
    workflows: ["SLO"]
    types:
      - completed

jobs:
  remove-slo-label:
    runs-on: ubuntu-latest
    if: always() && github.event.workflow_run.repository.full_name == 'ydb-platform/ydb-go-sdk'
    permissions:
      issues: write
    steps:
      - name: Remove SLO label
        uses: actions/github-script@v7
        with:
          script: |
            const prList = context.payload.workflow_run.pull_requests;
            if (!prList || prList.length === 0) {
              core.info('No pull request associated with this workflow run.');
              return;
            }
            const prNumber = prList[0].number;
            const label = 'SLO';
            try {
              await github.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                name: label
              });
              core.info(`Removed label "${label}" from PR #${prNumber}.`);
            } catch (error) {
              if (error.status === 404) {
                core.info(`Label "${label}" not found on PR #${prNumber}.`);
              } else {
                core.setFailed(`Failed to remove label: ${error.message}`);
              }
            }
